/*
 * RPi4 ARM64 boot relocator stub -- DOCUMENTATION ONLY
 *
 * This source file is a frozen reference snapshot. The actual stub used
 * by the boot image is regenerated by scripts/mksdcard.py at build time
 * because the seL4 elfloader entry address and total payload size both
 * change with every build. Do not assemble this file directly -- the
 * literal addresses and sizes below correspond to v0.4.95-era builds
 * and will not match a fresh build of main.
 *
 * What the stub does:
 *   1. RPi4 firmware always relocates ARM64 images to 0x80000, ignoring
 *      kernel_address. The seL4 elfloader is linked at a much higher
 *      address (~0x372c000 on v0.4.131, varies with image size). If
 *      seL4 ran from 0x80000 the kernel load would clobber the loader.
 *   2. This 4KB stub at 0x80000 finds itself via PC-relative ADR, copies
 *      the full payload starting at +4096 to its true link address, and
 *      branches there. x0 (DTB pointer from firmware) is preserved.
 *
 * What changes per build (regenerated by mksdcard.py):
 *   - .quad at offset 0x10: total file size (stub + payload)
 *   - movz/movk x1: destination address = ELF entry point
 *   - movz/movk x2: payload size in bytes
 *
 * What never changes:
 *   - Magic 0x644d5241 ("ARMd") at offset 0x30 (firmware sniff)
 *   - Initial branch + 64-byte ARM64 image header layout
 *   - Cache invalidation sequence after copy
 *
 * See hw/rpi4/BOOT_NOTES.md and scripts/mksdcard.py (relocator function).
 */
.section .text
.global _start
_start:
    b relocate
    .word 0
    .quad 0
    .quad 1361376
    .quad 0
    .quad 0
    .quad 0
    .word 0x644d5241
    .word 0
    .quad 0
relocate:
    mov x20, x0
    msr daifset, #0xf
    adr x5, _start
    mov x0, x5
    add x0, x0, #4096
    movz x1, #0xc000
    movk x1, #0x370, lsl #16
    movz x2, #0xb5e0
    movk x2, #0x14, lsl #16
    mov x10, x1
1:  ldp x3, x4, [x0], #16
    stp x3, x4, [x1], #16
    subs x2, x2, #16
    b.gt 1b
    dsb sy
    isb
    ic iallu
    dsb sy
    isb
    mov x0, x20
    br x10
.balign 4096
